package vn.edu.ltweb.jwtmvc.auth; import jakarta.validation.Valid; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import vn.edu.ltweb.jwtmvc.security.TokenService; import vn.edu.ltweb.jwtmvc.user.*;
@RestController @RequestMapping("/auth") public class AuthApiController {final UserService users; final TokenService tokens; final long expiry; public AuthApiController(UserService u,TokenService t,@Value("${security.jwt.expiration-seconds}")long e){users=u;tokens=t;expiry=e;} @PostMapping("/signup") UserResponse signup(@Valid @RequestBody RegisterRequest r){return users.register(r);} @PostMapping("/login") LoginResponse login(@Valid @RequestBody LoginRequest r){AppUser u=users.findByEmail(r.email());if(!users.passwordMatches(r.password(),u.getPassword()))throw new org.springframework.security.authentication.BadCredentialsException("Invalid credentials");return new LoginResponse(tokens.issue(u.getEmail()),"Bearer",expiry);}}
